from itertools import combinations, product
import heapq
from collections import Counter


def ledger(data, priority, tax_base, refund):
    def rounded(n, mode):
        return (n + 5000) // 10000 if mode == "half_up" else n // 10000

    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        eid = event.get("id", "anonymous:" + str(pos))
        key = ((event.get("revision", 0), pos) if priority == "revision_first"
               else (event.get("sequence", 0), event.get("revision", 0), pos))
        if eid not in chosen or key > chosen[eid][0]:
            chosen[eid] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        base = net if tax_base == "discounted" else raw
        tax = rounded(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if refund and event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def dependency_solver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    choices = []
    for name in names:
        rows = [r for r in packages[name]
                if r["version"] not in data.get("blocked", {}).get(name, [])
                and (name not in data.get("pins", {}) or
                     r["version"] == data["pins"][name])]
        choices.append([None] + rows)

    best = None
    bestvec = None
    for selection in product(*choices):
        installed = {n: row for n, row in zip(names, selection) if row is not None}
        constraints = {}
        for name, (lo, hi) in data["roots"].items():
            constraints.setdefault(name, []).append((lo, hi))
        reached = set()
        edges = {}
        stack = list(constraints)
        valid = True
        while stack and valid:
            name = stack.pop()
            row = installed.get(name)
            if row is None:
                valid = False
                break
            ver = row["version"]
            if any(not lo <= ver <= hi for lo, hi in constraints.get(name, [])):
                valid = False
                break
            if name in reached:
                continue
            reached.add(name)
            edges[name] = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                lo, hi = dep["min"], dep["max"]
                constraints.setdefault(other, []).append((lo, hi))
                edges[name].append(other)
                if other not in reached:
                    stack.append(other)
        if not valid or reached != set(installed):
            continue
        active, done = set(), set()
        def visit(n):
            if n in active:
                return False
            if n in done:
                return True
            active.add(n)
            if any(not visit(x) for x in edges.get(n, [])):
                return False
            active.remove(n)
            done.add(n)
            return True
        if not all(visit(n) for n in edges):
            continue
        vec = tuple(installed[n]["version"] if n in installed else -1 for n in names)
        if bestvec is None or vec > bestvec:
            bestvec, best = vec, {n: installed[n]["version"] for n in names if n in installed}
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def quota_solver(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    jobs = [j for j in jobs if j["id"] not in blocked]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    for subset in combinations(jobs, k):
        ids = {j["id"] for j in subset}
        if not mandatory <= ids:
            continue
        counts = Counter(j["group"] for j in subset)
        if any(not lo <= counts.get(g, 0) <= hi
               for g, (lo, hi) in quotas.items()):
            continue
        timeline = []
        for j in subset:
            timeline.append((j["start"], 1))
            timeline.append((j["end"], -1))
        # At equal times, process ends before starts (half-open intervals).
        active = 0
        good = True
        for _, delta in sorted(timeline, key=lambda x: (x[0], x[1])):
            active += delta
            if active > 2:
                good = False
                break
        if not good:
            continue
        ordered = tuple(sorted(j["id"] for j in subset))
        value = sum(j["value"] for j in subset)
        if best_value is None or value > best_value or (value == best_value and ordered < best_ids):
            best_value, best_ids = value, ordered
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def route_solver(data):
    required = data.get("required", [])
    bits = {node: 0 for node in range(data["n"])}
    for i, node in enumerate(required):
        bits[node] |= 1 << i
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    start = data["start"]
    initial = (data["source"], bits[data["source"]], data["coupons"])
    dist = {initial: start}
    heap = [(start, *initial)]
    while heap:
        time, node, mask, left = heapq.heappop(heap)
        state = (node, mask, left)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(left, edge["duration"])]
            if left:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((left - 1, duration))
            for newleft, duration in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = (edge["v"], mask | bits[edge["v"]], newleft)
                if arrival < dist.get(nxt, float("inf")):
                    dist[nxt] = arrival
                    heapq.heappush(heap, (arrival, *nxt))
    return {"arrival": None}


