    "component_01": lambda d: ledger(d, "revision_first", "discounted", False),
    "component_02": lambda d: ledger(d, "sequence_first", "discounted", True),
    "component_03": lambda d: ledger(d, "revision_first", "original", False),
    "component_04": lambda d: ledger(d, "sequence_first", "original", True),
    "component_05": lambda d: ledger(d, "revision_first", "discounted", True),
    "component_06": dependency_solver,
    "component_07": quota_solver,
    "component_08": route_solver,
}

